   "q": "<style>.katex-display{overflow-x:auto;overflow-y:hidden;padding:2px 0}</style><span style=\"display:block;font-size:13px;font-weight:600;color:var(--muted);margin-bottom:8px\">Repeat Assessment · 1 Feb 2024 · Part I (g) · 4 pts</span><span style=\"display:block;font-size:17px;font-weight:400;line-height:1.5\">Let \\(f:[0,1]\\to[0,1]\\) be a continuous map. Then the equation <span style=\"display:inline-block;border:1.5px solid currentColor;border-radius:5px;padding:0 6px;margin:0 2px;font-size:.78em;line-height:1.35;font-weight:700;vertical-align:.08em\">1</span> has at least one solution, as a consequence of the Brouwer Fixed Point Theorem.</span><details style=\"margin-top:12px;font-size:14px;font-weight:500\"><summary style=\"cursor:pointer;color:var(--muted)\">Show original exam item</summary><img src=\"img/feb24-g.png\" alt=\"Original exam item g\" loading=\"lazy\" style=\"display:block;width:100%;height:auto;margin-top:8px;border-radius:8px;background:#fff;border:1px solid var(--line)\"></details>",
